import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    w = int(data[1])

    a = list(map(int, data[2:2+n]))
    b = list(map(int, data[2+n:2+n+w]))

    def z_function(s):
        n = len(s)
        z = [0] * n
        l, r = 0, 0
        for i in range(1, n):
            if i <= r:
                z[i] = min(r - i + 1, z[i - l])
            while i + z[i] < n and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > r:
                l, r = i, i + z[i] - 1
        return z

    b_hash = hash(tuple(b))
    count = 0

    for i in range(n - w + 1):
        segment = a[i:i+w]
        if hash(tuple(segment)) == b_hash and segment == b:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
